import os,json,csv,hashlib,zipfile
from pathlib import Path
import numpy as np
from soapypower.coherent_features import coherent_features
import argparse,tempfile
parser=argparse.ArgumentParser(description='Reprocess the antenna/termination bundles and six archived 920 MHz retune IQ captures using held-out phase qualification. No new acquisition or automatic filtering.')
parser.add_argument('antenna_directory',type=Path)
parser.add_argument('termination_directory',type=Path)
parser.add_argument('--retunes',type=Path,required=True,help='Directory with IQ at RX centers 910, 913, 915, 917, 923, 925 MHz')
parser.add_argument('-o','--output',type=Path)
args=parser.parse_args();source=args.antenna_directory.resolve();reference=args.termination_directory.resolve();out=(args.output or source/'phase-enhanced').resolve();out.mkdir(parents=True,exist_ok=True);retunes=args.retunes.resolve();centers=[70,100,400,915,1800,2440,3500,5800,6000];allrows=[];results={};packed={};dcrows=[]
for center in centers:
 z=np.load(source/f'iq-{center}M-g20-dcon.npz')['iq'];r=coherent_features(z,56e6);results[center]=r
 assert r['training_sample_stop_exclusive']==r['validation_sample_start']==524288
 for c in r['candidates']:
  row=dict(rx_center_mhz=center,rf_hz_local_coordinate=center*1e6+c['baseband_hz'],**c);allrows.append(row)
 packed[f'{center}M__frequency_hz']=r['frequency_hz'];packed[f'{center}M__validation_psd']=r['validation_psd']
 dcrows.append(dict(rx_center_mhz=center,dc_trial_mean_power_before=r['dc_trial_mean_power_before'],dc_trial_mean_power_after=r['dc_trial_mean_power_after'],dc_trial_improvement_db=float(10*np.log10(max(r['dc_trial_mean_power_before'],1e-300)/max(r['dc_trial_mean_power_after'],1e-300))),applied_to_source=False))
 for i,t in enumerate(r['traces']):
  for k,v in t.items():packed[f'{center}M__candidate{i}__'+k]=v
 for c in r['candidates']:print('CANDIDATE',center,round(c['baseband_hz']),round(c['validation_phase_lock'],3),c['accepted'],flush=True)
accepted=[r for r in allrows if r['accepted']];assert len(accepted)>=1
with (out/'phase-qualified-candidates.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=allrows[0].keys());w.writeheader();w.writerows(allrows)
with (out/'dc-centering-trial.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=dcrows[0].keys());w.writeheader();w.writerows(dcrows)
retune_rows=[];retune_results={}
for center in [910,913,915,917,923,925]:
 z=np.load(retunes/f'iq-{center}M-g20-dcon.npz')['iq'];meta=json.loads((retunes/f'iq-{center}M-g20-dcon.json').read_text());assert meta['integrity']['continuity']=='verified';r=coherent_features(z,56e6);retune_results[center]=r
 for c in r['candidates']:
  if c['accepted']:retune_rows.append(dict(rx_center_mhz=center,rf_hz_local_coordinate=center*1e6+c['baseband_hz'],**c))
with (out/'retune-qualified-lines.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=allrows[0].keys());w.writeheader();w.writerows(retune_rows)
near=[r for r in retune_rows if abs(r['rf_hz_local_coordinate']-920e6)<100000];assert len(near)>=4
xx=np.array([r['rx_center_mhz']*1e6 for r in near]);rf=np.array([r['rf_hz_local_coordinate'] for r in near]);bb=np.array([r['baseband_hz'] for r in near]);rf_slope=float(np.polyfit(xx-915e6,rf-920e6,1)[0]);bb_slope=float(np.polyfit(xx-915e6,bb,1)[0]);assert abs(rf_slope)<.01 and abs(bb_slope+1)<.01
terminated=coherent_features(np.load(reference/'iq-915M-g20-dcon.npz')['iq'],56e6);termnear=[c for c in terminated['candidates'] if c['accepted'] and abs(c['baseband_hz']-5e6)<100000];assert termnear
best=min(accepted,key=lambda c:abs(c['rf_hz_local_coordinate']-920e6));r=results[best['rx_center_mhz']];k=best['fft_bin'];idx=next(i for i,c in enumerate(r['candidates']) if c['fft_bin']==k);trace=r['traces'][idx]
for key in ('fine_frequency_hz','fine_validation_psd'):packed['selected__'+key]=r[key]
np.savez_compressed(out/'coherent-feature-data.npz',**packed)
os.environ.setdefault('MPLCONFIGDIR',str(Path(tempfile.gettempdir())/'soapypower-mpl-cache'))
