for a in allrows:axs[1].scatter(a['rx_center_mhz'],a['validation_phase_lock'],s=35 if a['accepted'] else 15,color='#ffbd70' if a['accepted'] else '#9aadc5',marker='*' if a['accepted'] else 'o')
