fcenter=best['rx_center_mhz']*1e6;local=920e6;shortx=(r['frequency_hz']+fcenter-local)/1e3;finex=(r['fine_frequency_hz']+fcenter-local)/1e3;shortmask=abs(shortx)<40;finemask=abs(finex)<40;axs[2].plot(shortx[shortmask],db(r['validation_psd'][shortmask]),'o-',ms=4,lw=.9,color='#73c8ff',label='Short-Hann Welch · spacing 6.836 kHz / ENBW 10.254 kHz');axs[2].plot(finex[finemask],db(r['fine_validation_psd'][finemask]),lw=.65,color='#ffbd70',label='Held-out long Hann · spacing 106.81 Hz / ENBW 160.22 Hz');axs[2].scatter((best['rf_hz_local_coordinate']-local)/1e3,db(best['coherent_density']),s=45,color='#7be0b8',label='Matched frequency frozen from training');axs[2].set_title('Phase-qualified line detail · 64× finer local FFT grid, not a 64× full-scan improvement',loc='left');axs[2].set_xlabel('Offset from nominal 920 MHz (kHz; local receiver coordinate)');axs[2].set_ylabel('dB(input power/Hz)');axs[2].legend(fontsize=8)
for part,color,label in [('training','#73c8ff','Training: model fitted'),('validation','#ffbd70','Held-out: prediction only')]:axs[3].scatter(trace['train_time_seconds' if part=='training' else 'validation_time_seconds']*1000,trace[part+'_phase_residual_deg'],s=7,color=color,label=label)
axs[3].axvline(524288/56e6*1000,ls='--',color='#9aadc5');axs[3].set_ylim(-180,180);axs[3].set_ylabel('Residual phase (°)');axs[3].set_xlabel('FFT-frame start inside this capture (ms)');axs[3].set_title(f'Frozen phase/frequency model predicts disjoint held-out samples · phase lock {best["validation_phase_lock"]:.3f}',loc='left');axs[3].legend(fontsize=8)
for a in axs:a.grid(alpha=.14)
fig.suptitle('Phase used for validation and coherent line inspection',x=.09,ha='left',y=.98,fontsize=22);fig.text(.09,.927,'Candidate selection and frequency/phase fitting use the first 524288 samples only; validation uses the disjoint second half.\nNo held-out refit, no RF-phase stitching across retunes and no automatic deletion. Modulated signals may fail the stationary-line test and remain valid RF.',color='#aec1da');fig.text(.09,.025,'Fine-resolution PSD peak height increases as ENBW narrows; this is not increased signal power or a calibrated processing-gain claim.\nThe long-Hann validation curve is one periodogram, with higher noise variance than Welch averaging. Frequency accuracy remains limited by the receiver reference.',color='#aec1da');fig.subplots_adjust(left=.09,right=.95,top=.875,bottom=.12,hspace=.5);save(fig,'phase-used-overview')
